1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up files the page away (the note slides off the
3	// top) and a fresh blank page is ready underneath — same gesture as the
4	// original app. Notes land in Feed via the desktop-compatible core.
5	
6	import { useNavigation } from "@react-navigation/native";
7	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
8	import { useEffect, useMemo, useRef, useState } from "react";
9	import {
10	  Pressable,
11	  StyleSheet,
12	  Text,
13	  TextInput,
14	  useWindowDimensions,
15	  View,
16	} from "react-native";
17	import { Gesture, GestureDetector } from "react-native-gesture-handler";
18	import Animated, {
19	  runOnJS,
20	  useAnimatedStyle,
21	  useSharedValue,
22	  withSpring,
23	  withTiming,
24	} from "react-native-reanimated";
25	import { useSafeAreaInsets } from "react-native-safe-area-context";
26	
27	import * as core from "@typenotes/mobile-core/core-api";
28	
29	import { CaptureSession } from "../lib/capture";
30	import type { RootStackParamList } from "../navigation";
31	import { useNotesStore } from "../state/notes-store";
32	import { useTheme } from "../theme";
33	
34	const SWIPE_DISTANCE = 90;
35	const SWIPE_VELOCITY = -900;
36	
37	export const CaptureScreen = () => {
38	  const theme = useTheme();
39	  const insets = useSafeAreaInsets();
40	  const navigation =
41	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
42	  const { height } = useWindowDimensions();
43	
44	  const [text, setText] = useState("");
45	  const [pageKey, setPageKey] = useState(0);
46	  const inputRef = useRef<TextInput>(null);
47	
48	  const session = useMemo(
49	    () =>
50	      new CaptureSession({
51	        createNote: async (content) => (await core.createNote({ content })).path,
52	        writeNote: core.writeNote,
53	        deleteNote: (path) => core.deleteItems([path]),
54	      }),
55	    []
56	  );
57	
58	  // Flush the draft when the screen loses focus (navigation away).
59	  useEffect(
60	    () => navigation.addListener("blur", () => void session.flush()),
61	    [navigation, session]
62	  );
63	
64	  const translateY = useSharedValue(0);
65	
66	  const commitPage = () => {
67	    void session.commit().then((path) => {
68	      if (path) {
69	        void useNotesStore.getState().refresh();
70	      }
71	    });
72	    // Remount the input so the new blank page appears with no text flash.
73	    setText("");
74	    setPageKey((key) => key + 1);
75	    translateY.value = 0;
76	  };
77	
78	  const pan = Gesture.Pan()
79	    // Only claim clearly-upward drags; leave taps, horizontal moves, and
80	    // downward scrolling to the text input.
81	    .activeOffsetY([-24, Number.MAX_SAFE_INTEGER])
82	    .failOffsetY(12)
83	    .onUpdate((event) => {
84	      translateY.value = Math.min(0, event.translationY);
85	    })
86	    .onEnd((event) => {
87	      const shouldCommit =
88	        event.translationY < -SWIPE_DISTANCE || event.velocityY < SWIPE_VELOCITY;
89	      if (shouldCommit) {
90	        translateY.value = withTiming(
91	          -height,
92	          { duration: 200 },
93	          (finished) => {
94	            if (finished) {
95	              runOnJS(commitPage)();
96	            }
97	          }
98	        );
99	      } else {
100	        translateY.value = withSpring(0, { damping: 20, stiffness: 300 });
101	      }
102	    });
103	
104	  const pageStyle = useAnimatedStyle(() => ({
105	    transform: [{ translateY: translateY.value }],
106	  }));
107	
108	  const onChange = (value: string) => {
109	    setText(value);
110	    session.onChange(value);
111	  };
112	
113	  return (
114	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
115	      <GestureDetector gesture={pan}>
116	        <Animated.View
117	          style={[
118	            styles.page,
119	            { backgroundColor: theme.colors.background, paddingTop: insets.top + 12 },
120	            pageStyle,
121	          ]}
122	        >
123	          <TextInput
124	            key={pageKey}
125	            ref={inputRef}
126	            style={[styles.input, { color: theme.colors.text }]}
127	            value={text}
128	            onChangeText={onChange}
129	            placeholder="Start typing…"
130	            placeholderTextColor={theme.colors.secondaryText}
131	            multiline
132	            autoFocus
133	            scrollEnabled
134	            textAlignVertical="top"
135	            keyboardAppearance={theme.dark ? "dark" : "light"}
136	          />
137	          <Text
138	            style={[
139	              styles.hint,
140	              { color: theme.colors.secondaryText, marginBottom: insets.bottom + 8 },
141	            ]}
142	          >
143	            swipe up for a new page
144	          </Text>
145	        </Animated.View>
146	      </GestureDetector>
147	
148	      <View style={[styles.toolbar, { top: insets.top + 8 }]}>
149	        <ToolbarButton label="Mic" onPress={() => navigation.navigate("Record")} />
150	        <ToolbarButton label="Feed" onPress={() => navigation.navigate("Feed")} />
151	      </View>
152	    </View>
153	  );
154	};
155	
