1	// The seam between the app and the Rust core.
2	//
3	// `RawCore` mirrors the UniFFI exports of crates/type-ffi one-to-one:
4	// structured inputs/outputs are JSON strings (the same serde shapes the
5	// desktop Tauri commands speak), and function names are the camelCase form
6	// uniffi-bindgen-react-native generates from the Rust snake_case exports.
7	//
8	// The app never imports the generated turbo module directly. Instead the
9	// entry point calls `setRawCore(...)` once with either the generated module
10	// (wired on a Mac — see the package README) or the in-memory mock
11	// (`mock-core.ts`) when the native library isn't built, e.g. in Expo Go or
12	// on CI. Everything else goes through `getRawCore()`.
13	
14	/** Host-implemented transcription backend (FFI foreign trait). */
15	export interface RawTranscriptionProvider {
16	  /** Stable identifier used in error messages, e.g. "apple-speech". */
17	  id(): string;
18	  /** Transcribe the audio file at `audioPath` (absolute) into plain text. */
19	  transcribe(audioPath: string): string | Promise<string>;
20	}
21	
22	export interface RawCore {
23	  /** Must be called before anything else. Idempotent across JS reloads. */
24	  initCore(appDataDir: string, documentsDir: string | undefined): void | Promise<void>;
25	
26	  // ── Notes ──
27	  getTree(): Promise<string>;
28	  readNote(path: string): Promise<string>;
29	  createNote(argsJson: string): Promise<string>;
30	  writeNote(path: string, content: string): Promise<void>;
31	  setNoteTimestamp(argsJson: string): Promise<void>;
32	  updateNoteMarkers(argsJson: string): Promise<void>;
33	  getNoteMeta(path: string): Promise<string>;
34	  listNotePreviews(paths: string[]): Promise<string>;
35	  moveItems(items: string[], destination: string): Promise<void>;
36	  deleteItems(items: string[]): Promise<void>;
37	  renameItem(path: string, newName: string): Promise<string>;
38	  setOrder(argsJson: string): Promise<void>;
39	
40	  // ── Working folders ("profiles") + device app config ──
41	  getProfiles(): Promise<string>;
42	  createProfile(argsJson: string): Promise<string>;
43	  setActiveProfile(profileId: string): Promise<string>;
44	  setProfileNotesRoot(profileId: string, notesRoot: string): Promise<string>;
45	  updateProfile(argsJson: string): Promise<string>;
46	  deleteProfile(profileId: string): Promise<string>;
47	  updateProfileSettings(argsJson: string): Promise<string>;
48	  updateAppConfig(argsJson: string): Promise<string>;
49	  createProfilesBackupZip(): Promise<string>;
50	  exportProfilesToDocuments(): Promise<string>;
51	
52	  // ── Git sync ──
53	  generateSshKey(): Promise<string>;
54	  getSshPublicKey(): Promise<string | undefined>;
55	  deleteSshKey(): Promise<void>;
56	  getGitStatus(): Promise<string>;
57	  getGitHistory(argsJson: string | undefined): Promise<string>;
58	  connectGitRepo(argsJson: string): Promise<string>;
59	  gitPull(argsJson: string): Promise<string>;
60	  gitPush(argsJson: string): Promise<string>;
61	
62	  // ── Recordings ──
63	  saveAudioRecording(argsJson: string): Promise<string>;
64	  queueRecordingTranscriptions(argsJson: string): Promise<string>;
65	  queueProviderTranscriptions(provider: RawTranscriptionProvider): Promise<string>;
66	  listRecordings(): Promise<string>;
67	  readRecordingAudio(path: string): Promise<string>;
68	
69	  // ── Security ──
70	  getSecurityState(): Promise<string>;
71	  enableSecurity(argsJson: string): Promise<string>;
72	  lockSecurity(): Promise<string>;
73	  unlockSecurity(argsJson: string): Promise<string>;
74	  setSecurityPreferences(argsJson: string): Promise<string>;
75	}
76	
77	let rawCore: RawCore | null = null;
78	
79	export const setRawCore = (core: RawCore) => {
80	  rawCore = core;
81	};
82	
83	export const isRawCoreSet = () => rawCore !== null;
84	
85	export const getRawCore = (): RawCore => {
86	  if (!rawCore) {
87	    throw new Error(
88	      "Rust core is not wired. Call setRawCore(...) at app startup — with the " +
89	        "generated native module (see packages/mobile-core/README.md) or with " +
90	        "createMockCore() for demo mode."
91	    );
92	  }
93	  return rawCore;
94	};
95

