1	// Wires a RawCore implementation and initializes the Rust core.
2	//
3	// On a real device build, generate the native module first (see
4	// packages/mobile-core/README.md), then wire it by replacing the mock below:
5	//
6	//   import * as generated from "@typenotes/mobile-core/generated";
7	//   setRawCore(generated);
8	//
9	// The import must stay commented out until codegen has run — Metro resolves
10	// imports statically and would fail the bundle otherwise. Without the native
11	// module the app boots against the in-memory mock ("demo mode"): fully
12	// interactive, nothing persisted, banner shown in the UI.
13	
14	import * as FileSystem from "expo-file-system/legacy";
15	
16	import * as generated from "@typenotes/mobile-core";
17	import { initCore } from "@typenotes/mobile-core/core-api";
18	import { isRawCoreSet, setRawCore } from "@typenotes/mobile-core/raw-core";
19	
20	/** expo-file-system returns file:// URIs; the Rust core wants plain paths. */
21	const uriToPath = (uri: string) => decodeURI(uri.replace(/^file:\/\//, ""));
22	
23	export type BootResult = {
24	  demoMode: boolean;
25	};
26	
27	export const bootCore = async (): Promise<BootResult> => {
28	  let demoMode = false;
29	  if (!isRawCoreSet()) {
30	    setRawCore(generated);
31	  }
32	
33	  // The app's Documents directory is user-visible in the Files app
34	  // (UIFileSharingEnabled + LSSupportsOpeningDocumentsInPlace), so working
35	  // folders created under it can be browsed and backed up by the user.
36	  const documents = FileSystem.documentDirectory
