35	/// Bridges the FFI trait onto the core port so queued jobs can call back into
36	/// the host implementation.
37	struct ForeignTranscriptionProvider(Arc<dyn TranscriptionProvider>);
38	
39	impl type_core::ports::recordings::TranscriptionProvider for ForeignTranscriptionProvider {
40	    fn id(&self) -> String {
41	        self.0.id()
42	    }
43	
44	    fn transcribe(&self, audio_path: &std::path::Path) -> Result<String, String> {
45	        self.0
46	            .transcribe(audio_path.to_string_lossy().into_owned())
47	            .map_err(|error| error.to_string())
48	    }
49	}
